@Override
public int read(byte[] b, int off, int len) throws IOException {
    fill();
    if (buffered > position) {
        len = Math.min(len, buffered - position);
        System.arraycopy(buffer, position, b, off, len);
        position += len;
        return len;
    } else {
        return -1;
    }
}
